"use client";

import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import type { z } from "zod";
import type { EnquiryInput } from "@/schemas/enquiry.schema";
import { buildQuestionsSchema } from "@/lib/enquiry/question-validation";
import { Button } from "@/components/ui/Button";

type FieldConfig = {
  name: keyof EnquiryInput;
  label: string;
  description: string;
  placeholder: string;
  type?: "text" | "date" | "email" | "tel";
  fullWidth?: boolean;
};

const requiredFields = new Set<keyof EnquiryInput>([
  "course", "name", "dob", "gender", "motherName", "fatherName", "address",
  "mobile1", "email", "class10Percent", "class12Percent",
]);


export function EnquiryForm() {
  const [questions, setQuestions] = useState<FormQuestion[] | null>(null);
  const [loadError, setLoadError] = useState(false);
  useEffect(() => { fetch('/api/form-questions', { cache: 'no-store' }).then(async response => { if (!response.ok) throw new Error(); setQuestions((await response.json()).data ?? []); }).catch(() => setLoadError(true)); }, []);
  if (loadError) return <div className="admin-alert" role="alert">Unable to load the enquiry form. Please refresh and try again.</div>;
  if (!questions) return <div className="card">Loading enquiry form...</div>;
  if (!questions.length) return <div className="card">The enquiry form is not available right now.</div>;
  return <DynamicQuestionForm questions={questions} />;
}

function DynamicQuestionForm({ questions }: { questions: FormQuestion[] }) {
  const [clientIp, setClientIp] = useState("Detecting...");
  const schema = buildQuestionsSchema(questions);
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<Record<string, string>>({ resolver: zodResolver(schema), mode: "onBlur", reValidateMode: "onChange", defaultValues: Object.fromEntries(questions.map(question => [question.field_key, ''])) });
  useEffect(() => { fetch("/api/client-ip", { cache: "no-store" }).then(response => response.json()).then(result => setClientIp(result.ip || "Unavailable")).catch(() => setClientIp("Unavailable")); }, []);
  async function onSubmit(answers: Record<string, string>) {
    try {
      const response = await fetch("/api/enquiries", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ answers, ...answers, signatureDataUrl: "" }) });
      const text = await response.text();
      const json = text ? JSON.parse(text) as { error?: string; message?: string; clientIp?: string } : {};
      if (!response.ok) throw new Error(json.error || json.message || `Submission failed with status ${response.status}.`);
      if (json.clientIp) sessionStorage.setItem("eduspray-submitted-ip", json.clientIp);
      window.location.href = "/enquiry/success";
    } catch (error) { alert(error instanceof Error ? error.message : "Unable to submit enquiry."); }
  }
  return <form className="card grid" onSubmit={handleSubmit(onSubmit)}><div className="form-grid">{questions.map(question => <div className={`field${question.type === 'textarea' ? ' field-full' : ''}`} key={question.id}><label htmlFor={question.field_key}>{question.label}{question.required && <span className="required-mark" aria-hidden="true"> *</span>}</label><span className="field-description">{question.placeholder || ''}</span>{question.type === 'textarea' ? <textarea id={question.field_key} rows={3} placeholder={question.placeholder ?? ''} aria-invalid={errors[question.field_key] ? "true" : "false"} {...register(question.field_key)} /> : question.type === 'select' ? <select id={question.field_key} defaultValue="" aria-invalid={errors[question.field_key] ? "true" : "false"} {...register(question.field_key)}><option value="">{question.placeholder || 'Select an option'}</option>{question.options.map(option => <option value={option} key={option}>{option}</option>)}</select> : <input id={question.field_key} type={question.type === 'phone' ? 'tel' : question.type} inputMode={question.type === 'phone' || question.type === 'number' ? 'numeric' : undefined} maxLength={question.max_length} placeholder={question.placeholder ?? ''} aria-invalid={errors[question.field_key] ? "true" : "false"} {...register(question.field_key)} />}{errors[question.field_key] && <span className="error">{String(errors[question.field_key]?.message ?? '')}</span>}</div>)}</div><Button className="form-submit" type="submit" disabled={isSubmitting}>{isSubmitting ? "Submitting..." : "Submit Enquiry"}</Button><p className="form-connection-status" aria-live="polite">Connection detected: <strong>{clientIp}</strong></p></form>;
}
export function EnquiryForm() {
  const [clientIp, setClientIp] = useState("Detecting...");
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<z.input<typeof enquirySchema>, unknown, EnquiryInput>({
    resolver: zodResolver(enquirySchema),
    mode: "onBlur",
    reValidateMode: "onChange",
    defaultValues: {
      gender: undefined,
    },
  });

  useEffect(() => {
    let active = true;

    fetch("/api/client-ip", { cache: "no-store" })
      .then((response) => response.json())
      .then((result: { ip?: string }) => {
        if (active) setClientIp(result.ip || "Unavailable");
      })
      .catch(() => {
        if (active) setClientIp("Unavailable");
      });

    return () => {
      active = false;
    };
  }, []);

  const mobileRegister = (name: "mobile1" | "mobile2") => {
    const registration = register(name);
    return {
      ...registration,
      onChange: (event: React.ChangeEvent<HTMLInputElement>) => {
        event.target.value = event.target.value.replace(/\D/g, "").slice(0, 10);
        registration.onChange(event);
      },
    };
  };

  const onSubmit = async (data: EnquiryInput) => {
    try {
      const res = await fetch("/api/enquiries", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ...data,
          signatureDataUrl: "",
        }),
      });

      // -------------------------------------------------------
      // Read response safely.
      // Prevents "Unexpected end of JSON input"
      // -------------------------------------------------------
      const text = await res.text();

      let json: {
        ok?: boolean;
        error?: string;
        message?: string;
        clientIp?: string;
      } = {};

      try {
        json = text ? JSON.parse(text) : {};
      } catch {
        console.error("Non-JSON API response:", text);

        throw new Error(
          `Server returned an invalid response (${res.status}). Check the terminal running Next.js.`
        );
      }

      if (!res.ok) {
        throw new Error(
          json.error ||
            json.message ||
            `Submission failed with status ${res.status}.`
        );
      }

      // -------------------------------------------------------
      // Success
      // -------------------------------------------------------
      if (json.clientIp) {
        sessionStorage.setItem("eduspray-submitted-ip", json.clientIp);
      }
      window.location.href = "/enquiry/success";
    } catch (error) {
      console.error("SUBMISSION ERROR:", error);

      alert(
        error instanceof Error
          ? error.message
          : "Unable to submit enquiry."
      );
    }
  };

  return (
    <form
      className="card grid"
      onSubmit={handleSubmit(onSubmit)}
    >
      <div className="form-grid">
        {fields.map(({ name, label, description, placeholder, type, fullWidth }) => (
          <div className={`field${fullWidth ? " field-full" : ""}`} key={name}>
            <label htmlFor={String(name)}>
              {label}{requiredFields.has(name) && <span className="required-mark" aria-hidden="true"> *</span>}
            </label>
            <span className="field-description">{description}</span>

            {name === "gender" ? (
              <select id="gender" aria-invalid={errors[name] ? "true" : "false"} defaultValue="" {...register(name)}>
                <option value="" disabled>{placeholder}</option>
                <option value="M">Male</option>
                <option value="F">Female</option>
                <option value="Other">Other</option>
              </select>
            ) : name === "address" ? (
              <textarea id="address" rows={3} placeholder={placeholder} aria-invalid={errors[name] ? "true" : "false"} {...register(name)} />
            ) : (
              <input id={String(name)} type={type ?? "text"} inputMode={name === "mobile1" || name === "mobile2" ? "numeric" : undefined} maxLength={name === "mobile1" || name === "mobile2" ? 10 : undefined} placeholder={placeholder} aria-invalid={errors[name] ? "true" : "false"} {...(name === "mobile1" || name === "mobile2" ? mobileRegister(name) : register(name))} />
            )}

            {errors[name] && (
              <span className="error">
                {String(
                  errors[name]?.message ?? ""
                )}
              </span>
            )}
          </div>
        ))}
      </div>

      <Button
        className="form-submit"
        type="submit"
        disabled={isSubmitting}
      >
        {isSubmitting
          ? "Submitting..."
          : "Submit Enquiry"}
      </Button>
      <p className="form-connection-status" aria-live="polite">
        Connection detected: <strong>{clientIp}</strong>
      </p>
    </form>
  );
}